@Mod("ftboss_bossprobe")
public final class ManorDandanMotionRuntimeProbeV1 {
    private record Plan(int variant,int rotation,Skill skill,ManorDifficulty difficulty){}
    private static final List<Plan> plans=new ArrayList<>();
    private static final List<String> checks=new ArrayList<>();
    private static final List<Map<String,Object>> rows=new ArrayList<>();
    private static ServerLevel level;
    private static ServerStartedEvent pendingStart;
    private static EasterBossEntity boss;
    private static Cow target,control;
    private static ManorFiveSkills controller;
    private static Plan plan;
    private static Vec3 origin;
    private static int index,age,callbacks,hits,phase;
    private static float damageTotal;
    private static boolean finished;
    private static boolean candidate=System.getProperty("ftboss.manormotion.mode","baseline").equals("candidate");
    private static Map<String,Object> helperEvidence=Map.of();
    private static final List<Map<String,Object>> motionSamples=new ArrayList<>();
    private static net.minecraft.nbt.CompoundTag motionData(){return ((net.farmingtales.ftboss.dandanmotion.MotionAccess)boss).dandanMotionData();}
    private static void motion(String phase,int duration){boolean expected=candidate&&plan.variant==1;net.minecraft.nbt.CompoundTag tag=motionData();if(!expected){require(!tag.contains("dandan_motion_clip"),"NoMotionWithoutOriginalControllerHookOrOtherVariant:"+plan.skill+":"+phase);}else{String clip=phase.equals("start")?(plan.skill==Skill.DANDAN_REAP?"reap_charge":"star_charge"):phase.equals("pulse")?(plan.skill==Skill.DANDAN_REAP?"reap_cut":"star_release"):(plan.skill==Skill.DANDAN_REAP?"settle":"star_charge");require(tag.getString("dandan_motion_clip").equals(clip),"ActualOriginalControllerMotionClip:"+plan.skill+":"+phase);require(tag.getInt("dandan_motion_ticks")==Math.max(1,Math.min(200,duration)),"ActualOriginalControllerMotionDuration:"+plan.skill+":"+phase);require(tag.getLong("dandan_motion_start")==level.getGameTime(),"ActualOriginalControllerMotionNativeTime:"+plan.skill+":"+phase);require(tag.getInt("dandan_motion_schema")==1,"ActualOriginalControllerMotionSchema:"+plan.skill+":"+phase);require(tag.getBoolean("dandan_motion_reverse")==(phase.equals("finish")&&plan.skill==Skill.DANDAN_STAR),"ActualOriginalControllerMotionReverse:"+plan.skill+":"+phase);}if(plan.variant==1)motionSamples.add(Map.of("skill",plan.skill.name(),"difficulty",plan.difficulty.name(),"phase",phase,"expectedOriginalHookPresent",expected,"data",tag.toString()));}

    public ManorDandanMotionRuntimeProbeV1(){NeoForge.EVENT_BUS.addListener(ManorDandanMotionRuntimeProbeV1::start);NeoForge.EVENT_BUS.addListener(ManorDandanMotionRuntimeProbeV1::tick);}
    private static void require(boolean value,String name){if(!value)throw new AssertionError(name);checks.add(name);}
    private static Cow cow(double x,double y,double z){Cow entity=EntityType.COW.create(level);require(entity!=null,"ActualCowFactory");entity.setNoAi(true);entity.setNoGravity(true);entity.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000.0);entity.setHealth(1000.0F);entity.moveTo(x,y,z,0,0);require(level.addFreshEntity(entity),"ActualCowNativeAdmission");return entity;}
    private static void prepare(){plan=plans.get(index);boss=FTEntities.EASTER_BOSS.get().create(level);require(boss!=null,"ActualBossFactory:"+plan.skill);boss.setVariant(plan.variant);boss.setChallengeDifficulty(plan.difficulty);boss.setNoAi(false);boss.setNoGravity(true);boss.moveTo(8,320,8,0,0);target=cow(12,320,8);control=cow(12,368,8);target.setOnGround(true);control.setOnGround(true);require(!ManorLivingTargets.airborne(target),"ExplicitGroundedCurrentSkillSelection:"+plan.skill+":"+plan.difficulty);boss.setTarget(target);control.setTarget(boss);controller=new ManorFiveSkills(boss);controller.restoreRotation(plan.rotation);controller.refreshAttackBonus();require(ManorLivingTargets.valid(boss,target),"OriginalLivingPolicyAccepts:"+plan.skill);require(level.getEntity(target.getUUID())==target,"ActualUuidResolvesTarget:"+plan.skill);List<net.minecraft.world.entity.LivingEntity> nearby=ManorLivingTargets.nearby(level,boss);require(nearby.contains(target)&&nearby.contains(control),"ActualNearbyIncludesTargetAndControl:"+plan.skill+":target="+nearby.contains(target)+":control="+nearby.contains(control)+":targetValid="+ManorLivingTargets.valid(boss,target)+":controlValid="+ManorLivingTargets.valid(boss,control)+":targetRelation="+(boss.getTarget()==target)+":controlRelation="+(control.getTarget()==boss));require(boss.hasLineOfSight(target),"ActualTargetLineOfSight:"+plan.skill);require(controller.tryStart(level,target)&&controller.isCasting(),"OriginalLivingSkillCastStarts:"+plan.skill);age=ManorBalanceHooks.fiveAge(CastReadability.fiveAge(plan.skill.windup-boss.getChallengeDifficulty().acceleratedTicks(plan.skill.windup),plan.skill),plan.skill);require(Math.abs(boss.getActionProgress(1.0F)-EasterCombatMath.progress(1.0F,Math.max(1,plan.skill.duration()-age),false))<0.000001F,"ActualPublicAnimationMatchesOriginalTiming:"+plan.skill+":"+plan.difficulty);motion("start",plan.skill.windup-age);origin=plan.skill.shape==Shape.WAVE||plan.skill.shape==Shape.BEAM||plan.skill.shape==Shape.CONE?boss.position():target.position();hits=0;damageTotal=0;}
    private static void finish(Throwable failure){if(finished)return;finished=true;Map<String,Object> report=new LinkedHashMap<>();report.put("cases",checks);report.put("rows",rows);report.put("plans",plans.stream().map(value->value.difficulty.name()+":"+value.skill.name()).toList());report.put("completedSkills",rows.size());report.put("naturalPostCallbacks",callbacks);report.put("failures",failure==null?0:1);if(failure!=null){failure.printStackTrace();report.put("failure",failure.toString());}report.put("manorDandanMotionExecutionAccepted",failure==null&&candidate);report.put("actualOriginalMotionControllerGapDemonstrated",failure==null&&!candidate);report.put("helperEvidence",helperEvidence);report.put("motionSamples",motionSamples);report.put("scope","Four original Dandan motion controller/entity lifecycle hooks;all26original casts across13skill types and2difficulties retain actual pulse damage/effects/timing/outside controls on natural ServerTick.Post callbacks. Existing native Mixin interface/helper/packet controls separately verified,not a new interface feature. Public grounded/health/hurt-cooldown fixture;no manual Entity.tick,private reflection,authenticated,natural Boss AI,client rendering or fullbattle claim;other echo/body/FX pending.");report.put("fullBossMigrationComplete",false);try{Files.writeString(Path.of("actual-manor-dandan-motion-probe.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));}catch(Exception problem){problem.printStackTrace();}}
    private static void policyControls(ServerStartedEvent event){EasterBossEntity actor=FTEntities.EASTER_BOSS.get().create(level);require(actor!=null,"PolicyControlActualBossFactory");actor.setVariant(0);actor.setNoAi(false);actor.moveTo(8,320,8,0,0);ManorFiveSkills skills=new ManorFiveSkills(actor);require(!skills.tryStart(level,null),"OriginalPolicyRejectsNull");require(!skills.tryStart(level,actor),"OriginalPolicyRejectsSelf");ArmorStand stand=EntityType.ARMOR_STAND.create(level);require(stand!=null,"ActualArmorStandFactory");stand.moveTo(12,320,8,0,0);require(!skills.tryStart(level,stand),"OriginalPolicyRejectsArmorStand");ServerLevel foreign=event.getServer().getLevel(net.minecraft.world.level.Level.NETHER);require(foreign!=null,"ActualOtherNativeLevel");Cow foreignCow=EntityType.COW.create(foreign);require(foreignCow!=null,"ActualForeignCowFactory");require(!skills.tryStart(level,foreignCow),"OriginalPolicyRejectsForeignLevelLiving");Cow eligible=cow(12,320,8);actor.setTarget(eligible);require(ManorLivingTargets.valid(actor,eligible),"PolicyPositiveCowIsActuallyValid");actor.setNoAi(true);require(!skills.tryStart(level,eligible),"ExistingNoAiRejectsLivingEntry");require(!skills.isCasting()&&skills.rotation()==0&&actor.getSkillCue().isEmpty(),"RejectedTargetsDoNotAdvanceRotationOrCreateCue");eligible.discard();stand.discard();foreignCow.discard();}
    private static void start(ServerStartedEvent event){try{level=event.getServer().overworld();for(int[] chunk:new int[][]{{0,0},{1,0},{3,3}}){level.setChunkForced(chunk[0],chunk[1],true);level.getChunk(chunk[0],chunk[1]);}require(event.getServer().getPlayerList().getPlayerCount()==0,"NoAuthenticatedOrFakePlayerFixture");for(ManorDifficulty difficulty:ManorDifficulty.values())for(int variant=0;variant<9;variant++)if(ManorFiveCombatRules.hasExpandedSkills(variant))for(int rotation=0;rotation<ManorFiveCombatRules.rotationLength(variant);rotation++){Skill selected=ManorFiveCombatRules.select(variant,rotation);if(selected!=null)plans.add(new Plan(variant,rotation,selected,difficulty));}require(plans.stream().map(value->value.variant).distinct().count()==6,"ActualExpandedSixVariantMatrix");pendingStart=event;phase=-1;}catch(Throwable failure){finish(failure);}}
    private static Vec3 point(int pulse){Vec3 center=origin;if(plan.skill.shape==Shape.ECHO){double angle=pulse*Math.PI*2/3;center=center.add(Math.cos(angle)*3,0,Math.sin(angle)*3);}double limit=Math.max(32,plan.skill.radius*2+16);for(double forward=0;forward<=limit;forward+=0.25)if(ManorFiveCombatRules.contains(plan.skill,pulse,forward,0,0,target.getBbWidth()*0.5))return center.add(forward,0,0);throw new AssertionError("No public-rule geometry point:"+plan.skill+":"+pulse);}
    private static void tick(ServerTickEvent.Post event){if(finished||level==null)return;try{callbacks++;require(callbacks<5000,"BoundedNaturalServerPost:"+callbacks);
        if(phase==-1){if(!level.isPositionEntityTicking(new net.minecraft.core.BlockPos(8,320,8)))return;require(level.isPositionEntityTicking(new net.minecraft.core.BlockPos(8,320,8)),"ActualForcedChunkEntityTickingBeforeQueryFixtures");require(plans.size()==26&&plans.stream().map(value->value.difficulty).distinct().count()==2,"All13SkillsAcrossNormalAndImpossible");helperEvidence=MotionContractChecksV3.verify(pendingStart);policyControls(pendingStart);prepare();phase=0;return;}
        if(phase==0){age++;int pulse=ManorFiveCombatRules.pulseAt(plan.skill,age);Vec3 position=pulse>=0?point(pulse):new Vec3(12,320,8);target.moveTo(position.x,position.y,position.z,0,0);target.setDeltaMovement(Vec3.ZERO);target.setHealth(target.getMaxHealth());target.invulnerableTime=0;float before=target.getHealth();controller.tick(level);if(pulse>=0){float actual=before-target.getHealth();require(actual>0,"ActualLivingSkillDamage:"+plan.skill+":"+pulse);require(!target.getActiveEffects().isEmpty(),"ActualLivingSkillEffects:"+plan.skill+":"+pulse);if(controller.isCasting())motion("pulse",plan.skill.interval);damageTotal+=actual;hits++;}require(control.getHealth()==1000.0F&&control.getActiveEffects().isEmpty(),"OutsideOriginalRangeControlUnaffected:"+plan.skill+":"+age);if(!controller.isCasting()){motion("finish",7);require(hits==plan.skill.pulses,"EveryOriginalCurrentPulseHitsActualLiving:"+plan.skill+":"+hits);require(age>=plan.skill.duration(),"ActualControllerCompletesAtExistingDuration:"+plan.skill);Map<String,Object> row=new LinkedHashMap<>();row.put("variant",plan.variant);row.put("difficulty",plan.difficulty.name());row.put("rotation",plan.rotation);row.put("skill",plan.skill.name());row.put("actualPulseHits",hits);row.put("expectedExistingPulses",plan.skill.pulses);row.put("actualSkillDamage",damageTotal);row.put("existingDurationAge",age);rows.add(row);target.discard();control.discard();index++;if(index<plans.size())prepare();else{index=plans.indexOf(plans.stream().filter(value->value.variant==1).findFirst().orElseThrow());prepare();target.discard();phase=1;}}}
        else if(phase==1){controller.tick(level);require(!controller.isCasting(),"RemovedLivingTargetCancelsExpandedCast");require(!motionData().contains("dandan_motion_clip"),"OriginalMotionClearedAfter:RemovedLivingTargetCancelsExpandedCast");control.discard();prepare();boss.setNoAi(true);phase=2;}
        else{float before=target.getHealth();controller.tick(level);require(!controller.isCasting(),"NoAiCancelsExpandedLivingCast");require(!motionData().contains("dandan_motion_clip"),"OriginalMotionClearedAfter:NoAiCancelsExpandedLivingCast");require(target.getHealth()==before,"InterruptedExpandedCastNoLivingDamage");target.discard();control.discard();finish(null);}
    }catch(Throwable failure){finish(failure);}}
}
